// Best efforts page: power curve of the selected year against all time.

import uPlot from "./vendor/uplot-1.6.32/uPlot.esm.js";
import { axisStyle, withAlpha } from "./theme-data.js";
import { chartColors, onThemeChange } from "./theme.js";

const fmt = (v) => (v == null ? "–" : `${Math.round(v).toLocaleString("de-DE")} W`);

export function showPowerCurve() {
  const data = JSON.parse(document.getElementById("power-data").textContent);
  const container = document.getElementById("power-curve");
  const readout = document.getElementById("power-readout");
  if (!data.labels?.length) return;
  let chart = draw(container, readout, data);
  onThemeChange(() => {
    chart.destroy();
    chart = draw(container, readout, data);
  });
}

function draw(container, readout, data) {
  const colors = chartColors();
  const x = data.labels.map((_, i) => i);
  const hasPeriod = data.periodLabel && data.period?.length;
  const series = [{}, { stroke: colors.muted, width: 2, dash: hasPeriod ? [6, 4] : undefined, points: { show: true, size: 5 } }];
  const values = [x, data.allTime];
  if (hasPeriod) {
    series.push({ stroke: colors.accent, width: 2.5, fill: withAlpha(colors.accent, 0.12), points: { show: true, size: 6 } });
    values.push(data.period);
  } else {
    series[1] = { stroke: colors.accent, width: 2.5, fill: withAlpha(colors.accent, 0.12), points: { show: true, size: 6 } };
  }
  const show = (i) => {
    if (i == null) i = 0;
    const parts = [`${data.labels[i]}:`];
    if (hasPeriod) parts.push(`${data.periodLabel} ${fmt(data.period[i])} ·`);
    parts.push(`Bestwert ${fmt(data.allTime[i])}`);
    readout.textContent = parts.join(" ");
  };
  show(null);
  const height = () => (container.clientWidth < 520 ? 220 : 280);
  const plot = new uPlot({
    width: container.clientWidth,
    height: height(),
    legend: { show: false },
    cursor: { drag: { x: false, y: false } },
    scales: { x: { time: false, range: [-0.3, x.length - 0.7] }, y: { range: (u, min, max) => [0, Math.max(100, max * 1.1)] } },
    axes: [
      axisStyle(colors, {
        splits: () => x,
        values: (u, ticks) => ticks.map((t) => (container.clientWidth < 520 && t % 2 ? "" : data.labels[t] ?? "")),
        size: 30,
      }),
      axisStyle(colors, { size: 48, values: (u, ticks) => ticks.map((t) => Math.round(t).toLocaleString("de-DE")) }),
    ],
    series,
    hooks: { setCursor: [(u) => show(u.cursor.idx)] },
  }, values, container);
  const resize = new ResizeObserver(() => plot.setSize({ width: container.clientWidth, height: height() }));
  resize.observe(container);
  return {
    destroy() {
      resize.disconnect();
      plot.destroy();
    },
  };
}
